    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.35)

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > budget:
            rich_opponents += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    my_urgency = 0
    if hp <= 2:
        my_urgency += 3
    elif hp <= 4:
        my_urgency += 1
    if no_water >= 1:
        my_urgency += 2

    if my_urgency >= 4:
        base = DAILY_SALARY * 0.95
    elif my_urgency >= 2:
        base = DAILY_SALARY * 0.78
    else:
        if highest_prev >= DAILY_SALARY * 0.9:
            base = DAILY_SALARY * 0.28 if hp > 4 else DAILY_SALARY * 0.88
        elif highest_prev >= DAILY_SALARY * 0.75:
            base = max(DAILY_SALARY * 0.52, highest_prev - 6)
        elif highest_prev > 0:
            base = max(DAILY_SALARY * 0.45, avg_prev + 2)
        else:
            base = DAILY_SALARY * 0.5

    base += scarcity * 6
    base += urgent_opponents * 1.5
    if rich_opponents >= len(alive_opponents) / 2.0:
        base += 3

    if budget < DAILY_SALARY * 0.8:
        base = min(base, budget * 0.7 + 5)

    if hp > 5 and no_water == 0 and highest_prev >= DAILY_SALARY * 0.9:
        base = min(base, DAILY_SALARY * 0.3)

    bid = max(0, min(budget, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day')

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)
    my_no_water_days = my_status.get('no_water_days', 0)

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids (immediate reaction only)
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base pressure estimate from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Risk controls: if low HP or already starving, bid more
    starvation_risk = (my_hp <= 2) or (my_no_water_days >= 2)

    # Supply-aware aggressiveness: when supply is tight, winning matters more
    # Convert supply to a rough tier without using it as an index.
    tight_supply = supply <= float(WATER_REQ) + 6.0  # heuristic for medium scenario

    # If someone bid extremely high yesterday, they likely had urgent need.
    # We avoid overpaying unless we are also in danger.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if starvation_risk or tight_supply:
            bid = min(my_budget, DAILY_SALARY * 0.65)
        else:
            bid = min(my_budget, DAILY_SALARY * 0.25)
        return max(0.0, float(bid))

    # Otherwise, try to slightly beat the strongest yesterday bid.
    # Use a small increment to counter simultaneity.
    increment = 1.5
    target = highest_prev_bid + increment

    # If we can afford it, sometimes outbid the second-highest to reduce variance.
    if prev_bids and second_prev_bid > 0 and tight_supply:
        target = max(target, second_prev_bid + 1.0)

    # Apply caps based on our health/budget.
    cap = DAILY_SALARY * (0.85 if starvation_risk else (0.6 if tight_supply else 0.5))
    bid = min(my_budget, cap, target)

    # Ensure we bid at least a minimal amount when we are at risk
    if starvation_risk:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.35))

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_BID = 1

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return int(min(my_status['budget'], MIN_BID))

    # Determine base bid based on my HP
    if my_status['hp'] <= 2:
        current_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] == 3:
        current_bid = DAILY_SALARY * 0.8
    elif my_status['hp'] == 4:
        current_bid = DAILY_SALARY * 0.65
    else:
        current_bid = DAILY_SALARY * 0.45

    # Collect opponent's previous bids
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_opp_bid = max(yesterday_bids)

        # React to high opponent bids
        if highest_prev_opp_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                current_bid = max(current_bid, highest_prev_opp_bid + 5)
            else:
                current_bid = max(current_bid, highest_prev_opp_bid + 10)
        # React to low opponent bids (only if my HP is good)
        elif highest_prev_opp_bid < DAILY_SALARY * 0.3:
            if my_status['hp'] > 4:
                current_bid = min(current_bid, highest_prev_opp_bid + 10)
                current_bid = max(current_bid, DAILY_SALARY * 0.1)

    # Consider overall supply scarcity
    total_water_required_by_all = WATER_REQ + sum(o['water_requirement'] for o in alive_opponents)
    current_supply = day_context['supply']

    if current_supply < total_water_required_by_all:
        shortfall_ratio = current_supply / total_water_required_by_all
        if shortfall_ratio < 0.7:
            if my_status['hp'] > 3:
                current_bid = max(current_bid, DAILY_SALARY * 0.7)
            else:
                current_bid = max(current_bid, DAILY_SALARY * 0.9)
        elif shortfall_ratio < 0.9:
            if my_status['hp'] > 3:
                current_bid = max(current_bid, DAILY_SALARY * 0.55)
            else:
                current_bid = max(current_bid, DAILY_SALARY * 0.75)
    else:
        if my_status['hp'] > 4:
            current_bid = min(current_bid, DAILY_SALARY * 0.3)

    final_bid = max(MIN_BID, current_bid)
    final_bid = min(my_status['budget'], final_bid)

    return int(final_bid)

